// Generated by AI, edited by humans

/**
 * CustomSelect — wraps a native <select> with a fully styled custom dropdown.
 * The original <select> is kept hidden so all existing `change` listeners continue to work.
 */
export class CustomSelect {
    private readonly select: HTMLSelectElement
    private readonly wrapper: HTMLDivElement
    private readonly trigger: HTMLButtonElement
    private readonly triggerLabel: HTMLSpanElement
    private readonly dropdown: HTMLUListElement
    private readonly sizer: HTMLDivElement
    private isOpen = false
    private boundClose: (e: MouseEvent) => void
    private boundKeydown: (e: KeyboardEvent) => void

    constructor(select: HTMLSelectElement) {
        this.select = select

        // Build wrapper
        this.wrapper = document.createElement('div')
        this.wrapper.className = 'custom-select'
        if (select.id) {
            this.wrapper.classList.add(`${select.id}-wrap`)
        }

        // Build trigger button
        this.trigger = document.createElement('button')
        this.trigger.type = 'button'
        this.trigger.className = 'custom-select-trigger'
        this.trigger.setAttribute('aria-haspopup', 'listbox')
        this.trigger.setAttribute('aria-expanded', 'false')

        this.triggerLabel = document.createElement('span')
        this.trigger.appendChild(this.triggerLabel)

        const arrow = document.createElementNS('http://www.w3.org/2000/svg', 'svg')
        arrow.setAttribute('viewBox', '0 0 24 24')
        arrow.setAttribute('fill', 'none')
        arrow.setAttribute('stroke', 'currentColor')
        arrow.setAttribute('stroke-width', '2')
        arrow.setAttribute('stroke-linecap', 'round')
        arrow.setAttribute('stroke-linejoin', 'round')
        arrow.setAttribute('class', 'custom-select-arrow')
        const path = document.createElementNS('http://www.w3.org/2000/svg', 'path')
        path.setAttribute('d', 'M6 9l6 6 6-6')
        arrow.appendChild(path)
        this.trigger.appendChild(arrow)

        // Build dropdown list
        this.dropdown = document.createElement('ul')
        this.dropdown.className = 'custom-select-dropdown'
        this.dropdown.setAttribute('role', 'listbox')

        // Build sizer
        this.sizer = document.createElement('div')
        this.sizer.className = 'custom-select-sizer'

        // Insert into DOM — replace select in place
        select.parentNode!.insertBefore(this.wrapper, select)
        this.wrapper.appendChild(this.trigger)
        this.wrapper.appendChild(this.sizer)
        this.wrapper.appendChild(this.dropdown)
        select.style.display = 'none'
        this.wrapper.appendChild(select)

        this.buildOptions()
        this.updateTriggerLabel()

        // Events
        this.trigger.addEventListener('click', () => this.toggle())

        this.boundClose = (e: MouseEvent) => {
            if (!this.wrapper.contains(e.target as Node)) this.close()
        }
        this.boundKeydown = (e: KeyboardEvent) => this.handleKeydown(e)

        // Keep in sync when native select changes programmatically
        this.select.addEventListener('change', () => {
            this.updateTriggerLabel()
            this.updateSelectedClass()
        })
    }

    public rebuild(): void {
        this.buildOptions()
        this.updateTriggerLabel()
    }

    private buildOptions(): void {
        this.dropdown.innerHTML = ''
        this.sizer.innerHTML = ''
        Array.from(this.select.options).forEach((opt) => {
            const li = document.createElement('li')
            li.className = 'custom-select-item'
            li.setAttribute('role', 'option')
            li.dataset.value = opt.value

            const text = opt.textContent ?? ''

            const contentWrap = document.createElement('span')
            contentWrap.className = 'custom-select-option-content'
            const labelSpan = document.createElement('span')
            labelSpan.textContent = text
            contentWrap.appendChild(labelSpan)

            li.appendChild(contentWrap)

            if (opt.selected) li.classList.add('selected')

            li.addEventListener('click', () => {
                this.select.value = opt.value
                this.select.dispatchEvent(new Event('change', { bubbles: true }))
                this.close()
            })

            this.dropdown.appendChild(li)

            // Add to sizer so wrapper fits largest option
            const sizerItem = document.createElement('div')
            sizerItem.className = 'sizer-item'
            sizerItem.appendChild(contentWrap.cloneNode(true))
            this.sizer.appendChild(sizerItem)
        })
    }

    private updateTriggerLabel(): void {
        const opt = this.select.options[this.select.selectedIndex]
        if (!opt) return
        const text = opt.textContent ?? ''

        this.triggerLabel.innerHTML = ''
        this.triggerLabel.className = 'custom-select-trigger-content'

        const textSpan = document.createElement('span')
        textSpan.textContent = text
        this.triggerLabel.appendChild(textSpan)

        this.updateSelectedClass()
    }

    private updateSelectedClass(): void {
        this.dropdown.querySelectorAll<HTMLLIElement>('.custom-select-item').forEach((li) => {
            li.classList.toggle('selected', li.dataset.value === this.select.value)
        })
    }

    private toggle(): void {
        this.isOpen ? this.close() : this.open()
    }

    private open(): void {
        this.isOpen = true
        this.wrapper.classList.add('open')
        this.trigger.setAttribute('aria-expanded', 'true')
        // Flip up if not enough space below
        const rect = this.wrapper.getBoundingClientRect()
        const spaceBelow = window.innerHeight - rect.bottom
        this.wrapper.classList.toggle('drop-up', spaceBelow < 280)
        document.addEventListener('click', this.boundClose, true)
        document.addEventListener('keydown', this.boundKeydown, true)
    }

    public close(): void {
        if (!this.isOpen) return
        this.isOpen = false
        this.wrapper.classList.remove('open')
        this.trigger.setAttribute('aria-expanded', 'false')
        document.removeEventListener('click', this.boundClose, true)
        document.removeEventListener('keydown', this.boundKeydown, true)
    }

    private handleKeydown(e: KeyboardEvent): void {
        if (e.key === 'Escape') {
            this.close()
            this.trigger.focus()
            return
        }

        const items = Array.from(this.dropdown.querySelectorAll<HTMLLIElement>('.custom-select-item'))
        const currentIndex = items.findIndex((li) => li.dataset.value === this.select.value)

        if (e.key === 'ArrowDown') {
            e.preventDefault()
            const next = (currentIndex + 1) % items.length
            items[next]?.click()
        } else if (e.key === 'ArrowUp') {
            e.preventDefault()
            const prev = (currentIndex - 1 + items.length) % items.length
            items[prev]?.click()
        } else if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault()
            this.toggle()
        }
    }
}
